   // Limit the frame size when PSRAM is not available\n      config.frame_size = FRAMESIZE_SVGA;\n      config.fb_location = CAMERA_FB_IN_DRAM;\n    }\n  } else {\n    // Best option for face detection/recognition\n    config.frame_size = FRAMESIZE_240X240;\n#if CONFIG_IDF_TARGET_ESP32S3\n    config.fb_count = 2;\n#endif\n  }\n\n  // camera init\n  esp_err_t err = esp_camera_init(&config);\n  if (err != ESP_OK) {\n    Serial.printf("Camera init failed with error 0x%x", err);\n    return;\n  }\n\n  sensor_t * s = esp_camera_sensor_get();\n  // initial sensors are flipped vertically and colors are a bit saturated\n  if (s->id.PID == OV3660_PID) {\n    s->set_vflip(s, 1); // flip it back\n    s->set_brightness(s, 1); // up the brightness just a bit\n    s->set_saturation(s, -2); // lower the saturation\n  }\n  // drop down frame size for higher initial frame rate\n  if(config.pixel_format == PIXFORMAT_JPEG){\n    s->set_framesize(s, FRAMESIZE_QVGA);\n  }\n\n// Setup LED FLash if LED pin is defined in camera_pins.h\n#if defined(LED_GPIO_NUM)\n  setupLedFlash(LED_GPIO_NUM);\n#endif\n\n  WiFi.begin(ssid, password);\n  WiFi.setSleep(false);\n\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(500);\n    Serial.print(".");\n  }\n  Serial.println("");\n  Serial.println("WiFi connected");\n\n  startCameraServer();\n\n  Serial.print("Camera Ready! Use \'http://");\n  Serial.print(WiFi.localIP());\n  Serial.println("\' to connect");\n}\n\nvoid loop() {\n  // Do nothing. Everything is done in another task by the web server\n  delay(10000);\n}\n'})}),"\n",(0,r.jsx)(n.p,{children:"Antes de subir el programa, necesitas cambiar el nombre de WiFi y la contrase\xf1a en el c\xf3digo por los tuyos. Despu\xe9s de subir el programa, si el XIAO ESP32C3 se conecta exitosamente a tu WiFi, su direcci\xf3n IP ser\xe1 impresa."}),"\n",(0,r.jsx)(n.admonition,{type:"caution",children:(0,r.jsx)(n.p,{children:"XIAO ESP32S3 Si realizas este proyecto por un tiempo prolongado, por favor presta ate